<script setup lang="ts">
import { onMounted,ref } from 'vue';import type { ProgressionOverviewView } from '@eclipse/shared';import { rpc } from '../core/rpc';
const data=ref<ProgressionOverviewView|null>(null),busy=ref(false),error=ref('');const load=async()=>{const r=await rpc<ProgressionOverviewView>('eclipse:progression:overview');if(r.ok)data.value=r.data;else error.value=r.code;};const claim=async(key:string)=>{busy.value=true;const r=await rpc<ProgressionOverviewView>('eclipse:progression:claim',{key});busy.value=false;if(r.ok)data.value=r.data;else error.value=r.code;};const tier=async(tier:number)=>{busy.value=true;const r=await rpc<ProgressionOverviewView>('eclipse:progression:claimTier',{tier});busy.value=false;if(r.ok)data.value=r.data;else error.value=r.code;};onMounted(()=>void load());
</script>
<template><section><div class="top"><div><small>ПРОГРЕСС</small><h2>{{data?.points??0}} очков сезона</h2></div><button @click="load">Обновить</button></div><p v-if="error" class="error">{{error}}</p><h3>Достижения и задания</h3><div class="grid"><article v-for="t in data?.tasks" :key="t.kind+t.key"><span>{{t.kind==='achievement'?'Достижение':t.kind==='daily'?'Daily':'Weekly'}}</span><strong>{{t.title}}</strong><p>{{t.description}}</p><small>{{t.progress}} / {{t.target}} · +${{t.rewardCash}} · +{{t.rewardPoints}} pts</small><button :disabled="busy||!t.completed||t.claimed" @click="claim(t.key)">{{t.claimed?'Получено':t.completed?'Забрать':'В процессе'}}</button></article></div><h3>Battle Pass · {{data?.seasonKey}}</h3><div class="tiers"><article v-for="t in data?.battlePass" :key="t.tier"><b>Уровень {{t.tier}}</b><span>{{t.requiredPoints}} pts</span><strong>${{t.rewardCash}}</strong><button :disabled="busy||!t.unlocked||t.claimed" @click="tier(t.tier)">{{t.claimed?'Получено':t.unlocked?'Забрать':'Закрыто'}}</button></article></div></section></template>
<style scoped>.top{display:flex;justify-content:space-between;align-items:center}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid article,.tiers article{display:flex;flex-direction:column;gap:7px;padding:13px;border:1px solid var(--e-border);border-radius:12px;background:var(--e-surface-1)}.grid span,.grid small,.tiers span{color:var(--e-text-muted)}.grid p{margin:0}.tiers{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}.error{color:#ff8585}button{padding:8px 10px;border:1px solid var(--e-border);border-radius:9px;background:var(--e-surface-2);color:var(--e-text-primary)}button:disabled{opacity:.45}</style>